export const hashFamily = (f: Family): string => {
  const w = new HashWriter();
  w.writeString("Family");
  if (f.attributes && f.attributes.length > 0) {
    w.writeString("attributes");
    w.writeHashList(f.attributes.map(hashAttribute));
  }
