const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const filePath = './semio/assets/semio/metabolism.kit.semio.json';
const d = JSON.parse(fs.readFileSync(filePath, 'utf8'));

// Collect unique family names from types and designs
const familyNames = new Set();
(d.types || []).forEach(t => (t.families || []).forEach(f => familyNames.add(f)));
(d.designs || []).forEach(dd => (dd.families || []).forEach(f => familyNames.add(f)));

// Create family entities with deterministic guids (uuid v4 from name)
const nameToGuid = {};
for (const name of familyNames) {
  // Use a simple deterministic guid based on name
  const hash = crypto.createHash('md5').update('family:' + name).digest('hex');
  const guid = [hash.slice(0,8), hash.slice(8,12), '4' + hash.slice(13,16), '8' + hash.slice(17,20), hash.slice(20,32)].join('-');
  nameToGuid[name] = guid;
}

// Create family objects, distributing ports (all ports go into a default family for now)
// Since we don't know which ports belong to which family, put all ports in a special family
// Actually, looking at the data, ports are shared across all types - they're kit-level interface definitions
// Let's create one family per unique name, with no ports initially
const families = [...familyNames].map(name => ({
  guid: nameToGuid[name],
  name: name
}));

// Move ports from kit level into families - but we need to decide which family gets which port
// For now, since ports are generic interface definitions, let's keep them all at the kit level... 
// Wait - the spec says ports move INTO families. Let me check if ports have any family association.

console.log('Family count:', families.length);
console.log('Port count:', (d.ports || []).length);
console.log('Families:', JSON.stringify(families, null, 2));
"

