node -e "
const fs = require('fs');
const crypto = require('crypto');

const filePath = './semio/assets/semio/metabolism.kit.semio.json';
const d = JSON.parse(fs.readFileSync(filePath, 'utf8'));

// Collect unique family names
const familyNames = new Set();
(d.types || []).forEach(t => (t.families || []).forEach(f => familyNames.add(f)));
(d.designs || []).forEach(dd => (dd.families || []).forEach(f => familyNames.add(f)));

// Create deterministic guids
function makeGuid(seed) {
  const hash = crypto.createHash('md5').update(seed).digest('hex');
  return [hash.slice(0,8), hash.slice(8,12), '4'+hash.slice(13,16), '8'+hash.slice(17,20), hash.slice(20,32)].join('-');
}

const nameToGuid = {};
for (const name of familyNames) nameToGuid[name] = makeGuid('family:'+name);

// Create family objects (no ports - ports stay in the default family)
// Put ALL ports into the first family alphabetically, or create a single 'Shared' family
// Actually: create families without ports. Ports are an interface definition that belongs to families.
// For now create one family per name, no ports (they can be added later)
const families = [...familyNames].map(name => ({
  guid: nameToGuid[name],
  name: name
}));

// Convert type families from string[] to FamilyId[]
for (const t of (d.types || [])) {
  if (t.families) t.families = t.families.map(f => ({ guid: nameToGuid[f] }));
}

// Convert design families from string[] to FamilyId[]
for (const dd of (d.designs || [])) {
  if (dd.families) dd.families = dd.families.map(f => ({ guid: nameToGuid[f] }));
}

// Remove kit.ports, add kit.families
delete d.ports;
d.families = families;

fs.writeFileSync(filePath, JSON.stringify(d, null, 2) + '\n');
console.log('Done. Families:', families.length, 'Types updated:', (d.types||[]).length, 'Designs updated:', (d.designs||[]).length);
"

