const fs = require('fs');
const crypto = require('crypto');

function makeGuid(seed) {
  const hash = crypto.createHash('md5').update(seed).digest('hex');
  return [hash.slice(0,8), hash.slice(8,12), '4'+hash.slice(13,16), '8'+hash.slice(17,20), hash.slice(20,32)].join('-');
}

// Fix diff files - convert ports diff to families diff, string families to FamilyId
const diffFiles = [
  './semio/assets/semio/metabolism.kit.diff.semio.json',
  './semio/assets/semio/metabolism.kit.diff.inverted.semio.json'
];

for (const fp of diffFiles) {
  const d = JSON.parse(fs.readFileSync(fp, 'utf8'));
  let changed = false;

  // Convert kit-level ports diff to families diff
  if (d.ports && !d.families) {
    // The ports diff was at kit level, now ports are inside families
    // We can't simply convert - the structure is different
    // For now, remove ports and leave families empty (will be recomputed)
    delete d.ports;
    changed = true;
  }

  // Convert type diff families from string[] to FamilyId[]
  if (d.types?.updated) {
    for (const u of d.types.updated) {
      if (u.diff?.families && Array.isArray(u.diff.families)) {
        u.diff.families = u.diff.families.map(f => typeof f === 'string' ? { guid: makeGuid('family:'+f) } : f);
        changed = true;
      }
    }
  }

  // Convert design diff families from string[] to FamilyId[]
  if (d.designs?.updated) {
    for (const u of d.designs.updated) {
      if (u.diff?.families && Array.isArray(u.diff.families)) {
        u.diff.families = u.diff.families.map(f => typeof f === 'string' ? { guid: makeGuid('family:'+f) } : f);
        changed = true;
      }
    }
  }

  if (changed) {
    fs.writeFileSync(fp, JSON.stringify(d, null, 2) + '\n');
    console.log('UPDATED', fp);
  }
}
